        }
        if lhs.nextCode != rhs.nextCode {
            return false
        }
        if lhs.iconId != rhs.iconId {
            return false
        }
        if lhs.tags != rhs.tags {
            return false
        }
        if lhs.isPinned != rhs.isPinned {
            return false
        }
        return true
    }

