        hasher.combine(currentCode)
        hasher.combine(remainingSeconds)
        hasher.combine(period)
        hasher.combine(isNearExpiry)
        hasher.combine(nextCode)
        hasher.combine(iconId)
        hasher.combine(tags)
        hasher.combine(isPinned)
